namespace Clc.Polaris.Api.UnitTests.SerializationAndModels.Json.Deserialization { [TestClass][UnitTest] public sealed class JobsPurchaseOrdersStatusGetResultTests { [TestMethod] public void RoundTripsDocumentedShape() { var json = """{"PAPIErrorCode":0,"JobID":"job","JobStatusID":3,"JobStatusDescription":"Succeeded"}"""; var r = System.Text.Json.JsonSerializer.Deserialize<JobsPurchaseOrdersStatusGetResult>(json)!; Assert.AreEqual("job", r.JobID); Assert.AreEqual(3, r.JobStatusID); Assert.AreEqual("Succeeded", r.JobStatusDescription); } } }
